using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Keynote.Midi;
using Keynote.Core;
using Keynote.Playback;
using Keynote.Online;
namespace Keynote.Tests;
public class RemappedCatalogTests {
 sealed class Handler(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> run) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken t)=>run(r,t); }
 static RemappedSong Item(byte[] bytes)=>new(Convert.ToHexStringLower(SHA256.HashData(bytes)),"Scale","Composer","https://www.mutopiaproject.org/cgibin/piece-info.cgi?id=1","Public Domain","Visual Pianos",1,8,0,2,"Mutopia","Two notes adjusted.");
 static HttpResponseMessage Json(object item)=>new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(item),Encoding.UTF8,"application/json")};
 static string Fixture=>Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid");
 [Fact] public async Task CatalogDownloadChecksAndImportsIntoExistingLibrary() { var bytes=await File.ReadAllBytesAsync(Fixture); var item=Item(bytes); var paths=new List<string>(); using var http=new HttpClient(new Handler((r,t)=>{paths.Add(r.RequestUri!.AbsolutePath); return Task.FromResult(paths.Count==1?Json(new[]{item}):new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)});})); var service=new RemappedCatalogService(http,new MidiDownloadService(http)); var result=Assert.Single(await service.ListAsync(CancellationToken.None)); var dir=Path.Combine(Path.GetTempPath(),"larp-remap-"+Guid.NewGuid().ToString("N")); try { var lib=new MidiLibraryService(dir,new MidiImporter()); var saved=await service.DownloadAsync(result,lib,null,CancellationToken.None); Assert.False(saved.Duplicate); Assert.Equal(1,saved.Entry.RecommendedOctave); Assert.Equal(8,new MidiImporter().Import(await lib.OpenAsync(saved.Entry,CancellationToken.None)).Notes.Count()); Assert.Equal("/api/remapped/songs/"+item.Sha256+"/midi",paths[1]); Assert.True((await service.DownloadAsync(result,lib,null,CancellationToken.None)).Duplicate); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task DownloadRejectsChecksumMismatchBeforeLibraryWrite() { var data=await File.ReadAllBytesAsync(Fixture); var item=Item(data) with {Sha256=new string('a',64)}; using var http=new HttpClient(new Handler((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(data)}))); var dir=Path.Combine(Path.GetTempPath(),"larp-remap-"+Guid.NewGuid().ToString("N")); var lib=new MidiLibraryService(dir,new MidiImporter()); try { await Assert.ThrowsAsync<InvalidDataException>(()=>new RemappedCatalogService(http,new MidiDownloadService(http)).DownloadAsync(item,lib,null,CancellationToken.None)); Assert.False(Directory.Exists(dir)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task RejectsUntrustedCatalogueSourceAndDuplicateHashes() { var item=Item(await File.ReadAllBytesAsync(Fixture)); foreach(var entries in new[]{new[]{item with {Source="http://127.0.0.1/"}},new[]{item,item}}) { using var http=new HttpClient(new Handler((r,t)=>Task.FromResult(Json(entries)))); await Assert.ThrowsAsync<InvalidDataException>(()=>new RemappedCatalogService(http,new MidiDownloadService(http)).ListAsync(CancellationToken.None)); } }
 [Fact] public async Task CatalogueCancellationPropagates() { using var http=new HttpClient(new Handler(async(r,t)=>{await Task.Delay(Timeout.Infinite,t);return Json(Array.Empty<RemappedSong>());})); using var cancel=new CancellationTokenSource(); var pending=new RemappedCatalogService(http,new MidiDownloadService(http)).ListAsync(cancel.Token); cancel.Cancel(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>pending); }
 [Fact] public async Task SeededArrangementsFitTheDocumentedPianoProfile() { var dir=Path.Combine(AppContext.BaseDirectory,"RemappedSeed"); var songs=JsonSerializer.Deserialize<RemappedSong[]>(await File.ReadAllTextAsync(Path.Combine(dir,"manifest.json")),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!; var profile=JsonSerializer.Deserialize<KeyboardMapping>(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","visual-pianos-c2-unverified.json")))!; Assert.Equal(14,songs.Length); foreach(var item in songs) { var path=Path.Combine(dir,item.Sha256+".mid"); var bytes=await File.ReadAllBytesAsync(path); Assert.Equal(item.Sha256,Convert.ToHexStringLower(SHA256.HashData(bytes))); var song=new MidiImporter().Import(path); Assert.Equal(item.KeptNotes,song.Notes.Count()); Assert.Empty(profile.Missing(song,item.Octave)); Assert.NotEmpty(PlaybackEngine.BuildEvents(song,profile,item.Octave)); } }
 [Fact] public void RealHttpClientIdentifiesTheApp() { using var http=MidiDownloadService.CreateClient(); Assert.Contains("larpiano/1.0",http.DefaultRequestHeaders.UserAgent.ToString()); }
 [Fact] public void DownloadAllowlistIsLimitedToExactCataloguePath() { var hash=new string('a',64); MidiDownloadService.ValidateEndpoint(new Uri("https://larpiano.portways.app/api/remapped/songs/"+hash+"/midi")); Assert.Throws<InvalidOperationException>(()=>MidiDownloadService.ValidateEndpoint(new Uri("https://larpiano.portways.app/private"))); Assert.Throws<InvalidOperationException>(()=>MidiDownloadService.ValidateEndpoint(new Uri("https://larpiano.portways.app/api/remapped/songs/"+hash+"/midi?redirect=1"))); }
}
